class LibraryCard { final int id; final String number; final DateTime issuedAt; final DateTime expiresAt; const LibraryCard({required this.id,required this.number,required this.issuedAt,required this.expiresAt}); Map<String,dynamic> toJson()=>{'id':id,'number':number,'issuedAt':issuedAt.toIso8601String(),'expiresAt':expiresAt.toIso8601String()}; factory LibraryCard.fromJson(Map<String,dynamic> j)=>LibraryCard(id:(j['id'] as num?)?.toInt()??0,number:j['number'] as String? ?? '',issuedAt:DateTime.tryParse(j['issuedAt'] as String? ?? '')??DateTime.now(),expiresAt:DateTime.tryParse(j['expiresAt'] as String? ?? '')??DateTime.now().add(const Duration(days:365))); }
class Reader { final int id; final String fullName; final String email; final String phone; final LibraryCard card; final DateTime? deletedAt; const Reader({required this.id,required this.fullName,required this.email,required this.phone,required this.card,this.deletedAt}); bool get isDeleted=>deletedAt!=null; Reader copyWith({int? id,String? fullName,String? email,String? phone,LibraryCard? card,DateTime? deletedAt,bool clearDeletedAt=false})=>Reader(id:id??this.id,fullName:fullName??this.fullName,email:email??this.email,phone:phone??this.phone,card:card??this.card,deletedAt:clearDeletedAt?null:(deletedAt??this.deletedAt)); Map<String,dynamic> toJson()=>{'id':id,'fullName':fullName,'email':email,'phone':phone,'card':card.toJson(),'deletedAt':deletedAt?.toIso8601String()}; factory Reader.fromJson(Map<String,dynamic> j)=>Reader(id:(j['id'] as num?)?.toInt()??0,fullName:j['fullName'] as String? ?? '',email:j['email'] as String? ?? '',phone:j['phone'] as String? ?? '',card:LibraryCard.fromJson(Map<String,dynamic>.from(j['card'] as Map? ?? {})),deletedAt:j['deletedAt']==null?null:DateTime.tryParse(j['deletedAt'].toString())); }
